function resolve(ref){const f=model.floors[ref.floor];if(!f)return null;return(ref.kind==='doors'?allConnections(f):ref.kind==='annotations'?window.KERN_OBJECTS.annotations(model,ref.floor):f[ref.kind]||[]).find(o=>o.id===ref.id);}
