getSelection=function(){const s=baseGet();if(!currentBuilding()||rendering)return s;for(const kind of kinds)if(s[kind])s[kind]=s[kind].filter(id=>canEditFloor(floorId)&&available(kind,id));return s;};
function clearSelection(){finishMove(true);finishWidthEdit(false);resetTransient(true);setReferences([],{paint:false});window.BuildingExports?.getViewer?.()?.selectRoom?.(null,null);render();}
// Every explicit floor-selection entry point commits this one view-state transition.
function transitionFloors(ids,active,{clear=false,navigate=false}={}){const next=[...new Set(ids)].filter(id=>model.floors[id]);finishMove(true);finishWidthEdit(false);resetTransient(true);const refs=clear?[]:references();floorId=next.includes(active)?active:next[0]||floorId;state().editFloors=next;for(const id of floorOrder())state().visible[id]=next.includes(id);setReferences(refs.filter(r=>next.includes(r.floor)),{paint:false});const retained=references().length>0;syncViewer({select:!retained,navigate});if(retained)window.BuildingExports?.getViewer?.()?.selectObjects?.(viewerSelection());render();saveView();return true;}
function selectFloor(id,{additive=false}={}){if(!model.floors[id])return false;const old=state().editFloors,next=additive?(old.includes(id)?old.filter(fid=>fid!==id):[...old,id]):[id];return transitionFloors(next,additive?floorId:id,{clear:!additive,navigate:!additive});}
function activateFloor(id){return selectFloor(id);}

const baseAddFloor=addFloor,baseRemoveFloor=removeFloor;addFloor=function(...args){const previous=floorId,result=baseAddFloor(...args);if(floorId!==previous)activateFloor(floorId);return result;};removeFloor=function(...args){const previous=floorId,result=baseRemoveFloor(...args);if(floorId!==previous)activateFloor(floorId);return result;};
