function setVisible(id,value){if(!model.floors[id])return;finishMove(true);if(!value)window.KERN_SHAPE_UI?.beforeAvailabilityChange?.({floor:id});state().visible[id]=!!value;if(!value)setReferences(references().filter(r=>r.floor!==id),{paint:false});syncViewer();render();saveView();}
function showAllFloors(){recordVisibility(floorOrder());syncViewer();render();saveView();}
function setFloorSelection(ids){return transitionFloors(ids,floorId);}
function toggleFloor(id){return selectFloor(id,{additive:true});}

function entries(fid=floorId){const f=model.floors[fid];if(!f)return[];return[...f.rooms.map(o=>({floor:fid,kind:'rooms',id:o.id,name:o.name||o.id,type:o.routeStair?.surface==='ramp'?'Ramp':o.routeStair||o.localSteps||isStair(o,fid)?'Stair':roomTypeLabels[o.type]||'Room',object:o})),...allConnections(f).map(o=>({floor:fid,kind:'doors',id:o.id,name:o.label||`${f.rooms.find(r=>r.id===o.a)?.name||o.a} → ${o.b==='outside'?'Outside':f.rooms.find(r=>r.id===o.b)?.name||o.b}`,type:o.kind==='window'?'Window':o.kind==='open'?'Opening':'Door',object:o})),...['symbols','services','primitives'].flatMap(kind=>(f[kind]||[]).map(o=>({floor:fid,kind,id:o.id,name:o.name||o.kind,type:kind==='primitives'?(o.wall===true?'Wall':window.KERN_PRIMITIVES.labels[o.primitive]):kind==='symbols'?'Item':'Service',object:o}))),...window.KERN_OBJECTS.annotations(model,fid).map(o=>({floor:fid,kind:'annotations',id:o.id,name:o.text||'Annotation',type:'Text',object:o}))];}
function selectLayer(kind,id,event={},fid=floorId){const ref={floor:fid,kind,id};if(!eligible(ref))return false;finishMove(true);finishWidthEdit(false);resetTransient(true,true);const old=references(),exists=old.some(r=>refKey(r)===refKey(ref));setReferences(event.shiftKey?(exists?old.filter(r=>refKey(r)!==refKey(ref)):[...old,ref]):[ref]);if(kind==='services'&&fid===floorId)window.KERN_OBJECT_UI?.setVisible(true);if(window.BuildingExports?.isThreeMode?.()){window.BuildingExports.getViewer()?.activateFloor(floorId,{preserveEditing:true});window.BuildingExports.getViewer()?.selectObjects?.(viewerSelection());document.body.classList.add('editing3d');}return true;}
function toggleObject(kind,id,field,fid=floorId){finishMove(true);window.KERN_SHAPE_UI?.beforeAvailabilityChange?.({floor:fid,kind,id});const s=state();s.objects[fid]??={};const o=s.objects[fid][key(kind,id)]??={};o[field]=!o[field];setReferences(references(),{paint:false});window.BuildingExports?.getViewer?.()?.selectRoom?.(null,null);render();saveView();}
const baseCanEdit=canEdit;canEdit=function(r){return !crossSelection()&&baseCanEdit(r)&&canEditFloor(floorId)&&available('rooms',r?.id);};
const baseRoomAt=roomAt;roomAt=function(p,exclude){return baseRoomAt(p,exclude,r=>canEditFloor(floorId)&&available('rooms',r.id));};
function blockedLayer(){notify('This layer is hidden or locked. Show and unlock it in Layers to edit.');return false;}
const baseRoomMenu=openRoomMenu;openRoomMenu=function(id,...args){if(!canEditFloor(floorId)||!available('rooms',id))return blockedLayer();return baseRoomMenu(id,...args);};
const baseDoorMenu=openConnectionMenu;openConnectionMenu=function(id,...args){if(!canEditFloor(floorId)||!available('doors',id))return blockedLayer();return baseDoorMenu(id,...args);};
const baseMenuAction=applyConnectionMenu;applyConnectionMenu=function(...args){if(connectionMenu&&!available(connectionMenu.kind==='room'?'rooms':'doors',connectionMenu.id)){closeConnectionMenu();return blockedLayer();}return baseMenuAction(...args);};
const baseRoomTypeOption=roomTypeOption;roomTypeOption=function(r,...args){const option=baseRoomTypeOption(r,...args);return r&&(!canEditFloor(floorId)||!available('rooms',r.id))?{...option,valid:false,reason:'Show and unlock this layer to edit'}:option;};
const baseAddCandidate=addCandidate;addCandidate=function(candidate){if(!canEditFloor(floorId))return blockedLayer();if(candidate?.door&&[candidate.door.a,candidate.door.b].filter(id=>id!=='outside').some(id=>!available('rooms',id)))return blockedLayer();return baseAddCandidate(candidate);};
