const baseRemoveConnections=removeConnections;removeConnections=function(ids,...args){if(!canEditFloor(floorId)||ids.some(id=>!available('doors',id)))return blockedLayer();return baseRemoveConnections(ids,...args);};
const baseNearest=nearestDoor;nearestDoor=function(...args){const d=baseNearest(...args);return d&&available('doors',d.id)?d:null;};

function geometryPolygons(r,fid){let detail=null;try{detail=(r.routeStair||r.localSteps||isStair(r,fid))?stairDetail(r,fid):null;}catch{}const polygons=detail?[...(detail.flights||[]),...(detail.landings||[])].map(p=>p.polygon).filter(p=>p?.length):[];return polygons.length?polygons:[window.KERN_SHAPES.points(r)];}
function ghostMarkup(id){const f=model.floors[id],edit=editable(id);let s=`<g class="visible-floor-overlay below-floor ${edit?'floor-edit-enabled':'floor-reference-only'}" data-ghost-floor="${esc(id)}" data-visible-floor="${esc(id)}">`;for(const r of roomPaintOrder(f)){if(objectState('rooms',r.id,id).hidden)continue;s+=`<g data-layer-floor="${esc(id)}" data-layer-kind="rooms" data-layer-id="${esc(r.id)}">${geometryPolygons(r,id).map(ps=>`<path d="M${ps.map(p=>p.join(' ')).join('L')}Z"/>`).join('')}<title>${esc(id+' · '+r.name+(edit?' · Shift-click to add to selection':' · enable editing in the floor list'))}</title></g>`;}for(const d of allConnections(f)){if(objectState('doors',d.id,id).hidden)continue;const g=doorGeometry(d,f);if(!g)continue;s+=`<g data-layer-floor="${esc(id)}" data-layer-kind="doors" data-layer-id="${esc(d.id)}">`;for(const q of g.segments||[g]){const a=q.p0||(q.axis==='h'?[q.start,q.fixed]:[q.fixed,q.start]),b=q.p1||(q.axis==='h'?[q.end,q.fixed]:[q.fixed,q.end]);s+=`<path class="ghost-opening" d="M${a}L${b}"/>`;}s+='</g>';}for(const kind of ['symbols','services','annotations','primitives'])for(const o of kind==='annotations'?window.KERN_OBJECTS.annotations(model,id):f[kind]||[]){if(objectState(kind,o.id,id).hidden)continue;const b=window.KERN_OBJECTS.bounds(o);s+=`<g data-layer-floor="${esc(id)}" data-layer-kind="${kind}" data-layer-id="${esc(o.id)}">${kind==='primitives'?`<path d="M${window.KERN_PRIMITIVES.points(o).map(p=>p.join(' ')).join('L')}Z"/>`:`<rect x="${b.x}" y="${b.y}" width="${Math.max(.1,b.w)}" height="${Math.max(.1,b.h)}"/>`}<title>${esc(id+' · '+(o.name||o.text||o.kind))}</title></g>`;}return s+'</g>';}
belowMarkup=function(){return floorOrder().filter(id=>id!==floorId&&visible(id)).reverse().map(ghostMarkup).join('');};
function filteredPlan(){const f=floor();if(!visible(floorId))return{...model,floors:{...model.floors,[floorId]:{...f,rooms:[],doors:[],externals:[],external:undefined,symbols:[],services:[],annotations:[],primitives:[]}}};const objects=state().objects[floorId]||{};if(!Object.values(objects).some(o=>o.hidden))return model;const next={...model,floors:{...model.floors}},copy={...f};next.floors[floorId]=copy;for(const kind of ['rooms','doors','symbols','services','annotations','primitives'])if(f[kind])copy[kind]=f[kind].filter(o=>!objectState(kind,o.id).hidden);copy.annotations=window.KERN_OBJECTS.annotations(model,floorId).filter(o=>!objectState('annotations',o.id).hidden&&(!o.sourceRoom||!objectState('rooms',o.sourceRoom).hidden));copy.rooms=copy.rooms.map(r=>{if(!r.zones)return r;const visibleRoom={...r};delete visibleRoom.zones;return visibleRoom;});const roomIds=new Set(copy.rooms.map(r=>r.id));copy.doors=copy.doors.filter(d=>roomIds.has(d.a)&&(d.b==='outside'||roomIds.has(d.b)));if(f.externals)copy.externals=f.externals.filter((d,i)=>roomIds.has(d.room)&&!objectState('doors','legacy-exterior-'+i+'-'+d.room).hidden);if(f.external&&(!roomIds.has(f.external.room)||objectState('doors','legacy-exterior-0-'+f.external.room).hidden))delete copy.external;return next;}
const baseMarkup=planMarkup;planMarkup=function(exporting=false,...rest){if(exporting)return baseMarkup(exporting,...rest);const original=model;try{renderSource=original;model=filteredPlan();rendering=true;return baseMarkup(exporting,...rest);}finally{model=original;rendering=false;renderSource=null;}};

// The old all-floor footprint panel is intentionally removed. Floor dimensions remain optional.
function refBounds(ref){const o=resolve(ref);if(!o)return null;if(ref.kind==='rooms')return o.routeStair?window.KERN_ROUTE_STAIRS.bounds(o):window.KERN_SHAPES.bounds(window.KERN_SHAPES.points(o));if(ref.kind==='doors'){const g=doorGeometry(o,model.floors[ref.floor]);if(!g)return null;const points=(g.segments||[g]).flatMap(q=>[q.p0||(q.axis==='h'?[q.start,q.fixed]:[q.fixed,q.start]),q.p1||(q.axis==='h'?[q.end,q.fixed]:[q.fixed,q.end])]);return window.KERN_SHAPES.bounds(points);}return window.KERN_OBJECTS.bounds(o);}
function viewerSelection(){return references().flatMap(ref=>{const o=resolve(ref),b=refBounds(ref),f=model.floors[ref.floor];return o&&b&&f?[{...ref,...b,z:ref.kind==='primitives'?(Number.isFinite(f.z)?f.z:0)+b.z:Number.isFinite(o.z)?o.z:f.z,height:ref.kind==='primitives'?b.height:Number.isFinite(o.height)?o.height:f.clearHeight??3,polygons:ref.kind==='rooms'?geometryPolygons(o,ref.floor):null}]:[];});}
function selectedBounds(refs=references()){const boxes=refs.map(refBounds).filter(Boolean);if(!boxes.length)return null;const x=Math.min(...boxes.map(b=>b.x)),y=Math.min(...boxes.map(b=>b.y));return{x,y,w:Math.max(...boxes.map(b=>b.x+b.w))-x,h:Math.max(...boxes.map(b=>b.y+b.h))-y};}
function selectionOverlay(){const refs=references();if(!crossSelection()&&!moving)return '';const b=selectedBounds(refs);if(!b)return '';const color='#a4b8f2';return `<g id="crossfloor-selection" class="crossfloor-selection">${refs.map(ref=>{const o=resolve(ref),box=refBounds(ref);if(!box)return '';return ref.kind==='rooms'?geometryPolygons(o,ref.floor).map(ps=>`<path d="M${ps.map(p=>p.join(' ')).join('L')}Z" fill="${color}" fill-opacity=".12" stroke="${color}" stroke-width=".1" pointer-events="none"/>`).join(''):`<rect x="${box.x}" y="${box.y}" width="${Math.max(.15,box.w)}" height="${Math.max(.15,box.h)}" fill="none" stroke="${color}" stroke-width=".1" pointer-events="none"/>`;}).join('')}<rect data-crossfloor-move="true" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" fill="none" stroke="${color}" stroke-width=".12" stroke-dasharray=".3 .15" pointer-events="stroke"/></g>`;}
const baseSelectionMarkup=selectionMarkup;selectionMarkup=function(...args){return crossSelection()?'':baseSelectionMarkup(...args);};
function paintOverlay(){document.querySelector('#crossfloor-selection')?.remove();$('plan').insertAdjacentHTML('beforeend',selectionOverlay());}
function cameraBox(){const b=viewBounds||(viewBounds=bounds());return `${b.x+(1-1/zoom)*b.w/2+pan.x} ${b.y+(1-1/zoom)*b.h/2+pan.y} ${b.w/zoom} ${b.h/zoom}`;}
const baseDraw=draw;draw=function(...args){references();const camera=cameraBox(),same=scene&&scene.model===model&&scene.revision===revision&&scene.floor===floorId&&scene.tool===tool&&scene.theme===theme&&scene.dim===$('dimensions').checked&&scene.outer===currentBuilding().view.outerDimensions&&scene.snap===snapSize();if(same&&scene.camera!==camera&&!drag&&!widthEdit&&!moving&&!window.KERN_SHAPE_UI?.isEditing?.()&&!window.KERN_ROTATE?.isEditing?.()){ $('plan').setAttribute('viewBox',camera);scene.camera=camera;refreshEditingOverlays();updateInteractionUI();return; }const r=baseDraw(...args);scene={model,revision,floor:floorId,tool,theme,dim:$('dimensions').checked,outer:currentBuilding().view.outerDimensions,snap:snapSize(),camera};if(window.BuildingExports?.isThreeMode?.())return r;paintOverlay();for(const node of $('plan').querySelectorAll('[data-room],[data-door],[data-extra]')){const kind=node.hasAttribute('data-room')?'rooms':node.hasAttribute('data-door')?'doors':node.dataset.extra,id=node.dataset.room||node.dataset.door||node.dataset.id;if(!available(kind,id)||!canEditFloor(floorId))node.classList.add('layer-locked');}return r;};
const baseSave=save;save=function(...args){revision++;return baseSave(...args);};
function validateProposal(proposal){validateImport(proposal.plan);try{for(const ref of proposal.analysis?.refs||proposal.selection||[])if(ref.kind==='rooms'){const r=proposal.plan.floors[ref.floor]?.rooms.find(o=>o.id===ref.id);if(r&&(r.routeStair||r.localSteps||r.stairTransition))window.KERN_STAIR_DETAIL?.build(proposal.plan,ref.floor,r.id);}}catch{throw Error('This edit could not produce stable stair geometry. Nothing was changed.');}}
function transformOptions(){return{guard:(ref,o,meta)=>{if(!available(ref.kind,ref.id,ref.floor))return 'Show and unlock '+ref.id+' on '+ref.floor+' first.';if(meta?.explicit&&ref.kind==='rooms'&&entryProtected(o,ref.floor))return window.KERN_SPACE_LOCK?.reviewable(ref.floor,ref.id)?o.name+' is locked. Select it and use the Space lock action in the inspector.':'This footprint follows its source. Make the cap independent before moving it.';if(o?.hidden)return 'The linked object '+ref.id+' is hidden.';if(o?.locked&&ref.kind==='rooms'&&!sourceFor(o,ref.floor)&&!isStair(o,ref.floor))return 'The linked object '+ref.id+' on '+ref.floor+' is locked.';return true;}};}
function moveSelection(dx,dy,refs=references()){finishMove(true);try{const proposal=window.KERN_SELECTION_TRANSFORM.translate(model,refs,dx,dy,transformOptions());validateProposal(proposal);if(!proposal.changed)return true;commit(()=>{model=proposal.plan;setReferences(proposal.selection||refs,{paint:false});});notify('Selection moved · one Undo restores all selected floors'+(proposal.analysis?.added?.length?' · linked geometry moved with it':'')+(proposal.analysis?.warnings?.length?' · '+proposal.analysis.warnings.map(w=>w.reason).join(' '):''));return true;}catch(error){notify(error.message);return false;}}
